// Etichetă pentru mesajul "nimic deschis acum" — cerut explicit: quando
// filtrul "deschis acum" ajunge la 0 rezultate (ex. seara târziu), în loc
// să lăsăm lista goală, arătăm un mesaj care trimite spre itinerarul AI —
// transformă un moment frustrant într-o oportunitate.
;
function buildHolidayRadarHtml(countryCode, lang) {
  const country = COUNTRIES[countryCode];
  if (!country || !country.config) return "";
  const T = HOLIDAY_RADAR_LABELS[lang] || HOLIDAY_RADAR_LABELS.uk;
  // uniune a sărbătorilor din toate brandurile țării: dată → { label, closed, reduced }
  const byDate = {};
  Object.keys(country.config).forEach((k) => {
    (country.config[k].holidays || []).forEach((h) => {
      if (!h || !h.date) return;
      const e = byDate[h.date] || (byDate[h.date] = { label: h.label || "", closed: 0, reduced: 0 });
      if (h.hours) e.reduced++; else e.closed++;
    });
  });
  const base = new Date(roNowParts().date + "T12:00:00Z");
  for (let off = 0; off <= 2; off++) {
    const d = new Date(base.getTime() + off * 86400000);
    const full = d.toISOString().slice(0, 10), md = full.slice(5);
    const e = byDate[full] || byDate[md];
    if (!e || (e.closed + e.reduced) < 2) continue; // doar sărbători care afectează mai multe branduri
    const when = off === 0 ? T.today : off === 1 ? T.tomorrow : T.after;
    const label = String(e.label).replace(/\s*\(.*\)\s*$/, "");
    const what = e.closed >= e.reduced ? T.closed : T.reduced;
    const tip = off === 0 ? "" : off === 1 ? ` ${T.tipTomorrow}` : ` ${T.tipAfter}`;
    return `<div class="holiday-radar" role="status">🗓️ <strong>${escapeHtml(when)}${label ? " — " + escapeHtml(label) : ""}:</strong> ${escapeHtml(what)}.${escapeHtml(tip)}</div>`;
  }
  return "";
}

