// Clasificarea (margarete / stele) afișată cu SVG — pe carduri și în antetul paginii cazării
function classificationBadgeHtml(type, n, size) {
  const v = Math.max(0, Math.min(5, parseInt(n, 10) || 0));
  if (!v) return "";
  const sz = size || 16;
  const daisy = DAISY_TYPES.includes(type);
  let one;
  if (daisy) {
    const petals = [0, 45, 90, 135, 180, 225, 270, 315].map((a) => `<ellipse cx="12" cy="5.4" rx="2.2" ry="3.7"${a ? ` transform="rotate(${a} 12 12)"` : ""}/>`).join("");
    one = `<svg width="${sz}" height="${sz}" viewBox="0 0 24 24" aria-hidden="true"><g fill="#ffffff" stroke="#6f7d94" stroke-width="1.2" stroke-linejoin="round">${petals}</g><circle cx="12" cy="12" r="2.7" fill="#f4b400" stroke="#d99a00" stroke-width="1"/></svg>`;
  } else {
    one = `<svg width="${sz}" height="${sz}" viewBox="0 0 24 24" aria-hidden="true" fill="#f5a623" stroke="#e09100" stroke-width="1" stroke-linejoin="round">${STAR_PATH}</svg>`;
  }
  const label = daisy ? `${v} ${v === 1 ? "margaretă" : "margarete"}` : `${v} ${v === 1 ? "stea" : "stele"}`;
  return `<span role="img" aria-label="${label}" style="display:inline-flex;gap:3px;vertical-align:middle;line-height:0">${Array(v).fill(one).join("")}</span>`;
}
