app.post("/api/cazare/contacteaza-suport", accommodationGate, async (req, res) => {
  const { email, message } = req.body || {};
  if (typeof email !== "string" || !EMAIL_RE.test(email.trim()) || email.length > 255) {
    res.status(400).json({ error: "invalid_email" });
    return;
  }
  if (typeof message !== "string" || !message.trim() || message.length > 1000) {
    res.status(400).json({ error: "invalid_message" });
    return;
  }
  const ipHash = hashIp(getClientIp(req));
  const rateOk = await checkRateLimit(ipHash, "cazare-contact-suport", 5, 60);
  if (!rateOk) { res.status(429).json({ error: "too_many_requests" }); return; }
  if (!RESEND_API_KEY) { res.status(503).json({ error: "not_configured" }); return; }
  try {
    const resp = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { "Authorization": `Bearer ${RESEND_API_KEY}`, "Content-Type": "application/json" },
      signal: AbortSignal.timeout(8000),
      body: JSON.stringify({
        from: "Opening Hours Today <cazare@programul-de-azi.ro>",
        to: ["marianarsene.ma@gmail.com"],
        replyTo: email.trim(),
        subject: `Cerere de suport — recuperare cont (${email.trim()})`,
        html: `<p><strong>De la:</strong> ${escapeHtml(email.trim())}</p><p><strong>Mesaj:</strong></p><p>${escapeHtml(message.trim()).replace(/\n/g, "<br>")}</p>`,
      }),
    });
    if (!resp.ok) { res.status(502).json({ error: "email_failed" }); return; }
    res.status(200).json({ ok: true });
  } catch (err) {
    console.error("contacteaza-suport a eșuat:", err.message);
    res.status(500).json({ error: "server_error" });
  }
});
app.post(
  "/api/cazare/upload-poza",
  accommodationGate,
  requireAccommodationOwnerApi,
  express.raw({ type: Object.keys(ACCOMMODATION_PHOTO_TYPES), limit: "4mb" }),
  async (req, res) => {
    const put = await getBlobPut();
    if (!put) { res.status(503).json({ error: getAccLang(req) === "en" ? "Photo uploads are not available right now." : "Încărcarea pozelor nu e disponibilă momentan." }); return; }
    const contentType = String(req.headers["content-type"] || "").split(";")[0].trim();
    const ext = ACCOMMODATION_PHOTO_TYPES[contentType];
    if (!ext || !Buffer.isBuffer(req.body) || !req.body.length || !fileMatchesDeclaredType(req.body, contentType)) {
      res.status(400).json({ error: getAccLang(req) === "en" ? "The file is not a valid JPG/PNG/WEBP photo (or it is too large)." : "Fișierul nu e o poză JPG/PNG/WEBP validă (sau e prea mare)." });
      return;
    }
    try {
      const pathname = `cazare/${req.accommodationOwner.ownerId}/${Date.now()}-${crypto.randomBytes(4).toString("hex")}.${ext}`;
      const blob = await put(pathname, req.body, {
        access: "public",
        token: BLOB_READ_WRITE_TOKEN,
        addRandomSuffix: true,
        contentType,
      });
      res.status(200).json({ url: blob.url });
    } catch (err) {
      console.error("upload-poza a eșuat:", err.message);
      res.status(500).json({ error: getAccLang(req) === "en" ? "The upload failed. Please try again." : "Încărcarea a eșuat. Încearcă din nou." });
    }
  }
);

// Integrare ANAF — verificare CUI, preia automat denumirea firmei, adresa
// sediului social și statusul de plătitor de TVA. API public, gratuit, fără
// cheie — verificat direct (interogare live) înainte de a scrie codul.
// Limită ANAF: 1 request/secundă per client — rate-limit-ăm noi înainte,
// ca să nu riscăm blocare de la ANAF dacă cineva apasă butonul repetat.
app.get("/api/cazare/verifica-cui", accommodationGate, requireAccommodationOwnerApi, async (req, res) => {
  const cuiRaw = String(req.query.cui || "").trim().replace(/^RO/i, "");
  if (!/^\d{2,10}$/.test(cuiRaw)) { res.status(400).json({ error: "invalid_cui" }); return; }
  const ipHash = hashIp(getClientIp(req));
  const rateOk = await checkRateLimit(ipHash, "verifica-cui", 15, 5);
  if (!rateOk) { res.status(429).json({ error: "too_many_requests" }); return; }
  try {
    const today = new Date().toISOString().slice(0, 10);
    const anafResp = await fetch("https://webservicesp.anaf.ro/api/PlatitorTvaRest/v9/tva", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify([{ cui: parseInt(cuiRaw, 10), data: today }]),
      signal: AbortSignal.timeout(8000),
    });
    if (!anafResp.ok) { res.status(502).json({ error: "anaf_unavailable" }); return; }
    const data = await anafResp.json();
    if (!data.found || !data.found.length) { res.status(404).json({ error: "not_found" }); return; }
    const g = data.found[0].date_generale || {};
    const tva = data.found[0].inregistrare_scop_Tva || {};
    res.status(200).json({
      denumire: g.denumire || "",
      adresa: g.adresa || "",
      nrRegCom: g.nrRegCom || "",
      platitorTva: !!tva.scpTVA,
    });
  } catch (err) {
    console.error("verifica-cui a eșuat:", err.message);
    res.status(502).json({ error: "anaf_error" });
  }
});

