    removeBtn.type = "button"; removeBtn.className = "acc-roomtype-remove"; removeBtn.textContent = "✕";
    removeBtn.addEventListener("click", function(){ card.remove(); });
    card.appendChild(removeBtn);
    var nameWrap = document.createElement("div");
    nameWrap.className = "acc-editable-field-wrap";
    var nameInput = document.createElement("input");
    nameInput.type = "text"; nameInput.className = "acc-white-input rm-name"; nameInput.maxLength = 60;
    nameInput.placeholder = LANG === "en" ? "e.g. Bedroom 1, Living room" : "ex. Dormitorul 1, Living";
    nameInput.value = roomData.name || ((LANG === "en" ? "Bedroom " : "Dormitorul ") + roomCounter);
