      if (!name) return;
      var typeSel = card.querySelector(".rt-type");
      var kitchenEl = card.querySelector(".rt-kitchen:checked");
      var amenities = [];
      card.querySelectorAll("[data-rt-amenity]:checked").forEach(function(cb){ amenities.push(cb.getAttribute("data-rt-amenity")); });
      var photosYes = card.querySelector(".rt-has-photos[value=yes]");
      var photos = (photosYes && photosYes.checked && card.__getPhotos) ? card.__getPhotos() : [];
