        name: name,
        unitType: typeSel ? typeSel.value : "",
        adults: card.querySelector(".rt-adults") ? card.querySelector(".rt-adults").value : "",
        children: card.querySelector(".rt-children") ? card.querySelector(".rt-children").value : "",
        rooms: rooms,
        bathroomCount: bathrooms.length,
