    var bathCounterWrap = document.createElement("div");
    bathCounterWrap.className = "acc-bed-counter";
    var bathMinus = document.createElement("button"); bathMinus.type = "button"; bathMinus.textContent = "−";
    var bathCountSpan = document.createElement("span");
    var bathroomsList = document.createElement("div");
    bathroomsList.className = "acc-rooms-list";
    var bathPlus = document.createElement("button"); bathPlus.type = "button"; bathPlus.textContent = "+";
    bathMinus.addEventListener("click", function(){ var v = parseInt(bathCountSpan.textContent, 10) || 0; if (v > 0) syncBathroomCount(bathroomsList, bathCountSpan, v - 1); });
