// ------------------------------------------------------------------
// Notificări push zilnice (Vercel Cron, vezi vercel.json): radarul de
// sărbători — „Mâine e Crăciun în România: magazinele sunt închise,
// cumpără azi.” Trimis doar abonaților din țara respectivă, o singură
// dată pe zi (last_holiday_push). Abonamentele expirate (404/410) se șterg.
// Protejat: Vercel trimite „Authorization: Bearer CRON_SECRET”.
// ------------------------------------------------------------------
function tomorrowHolidayFor(countryCode) {
  const country = COUNTRIES[countryCode];
  if (!country || !country.config) return null;
  const tomorrow = new Date(new Date(roNowParts().date + "T12:00:00Z").getTime() + 86400000).toISOString().slice(0, 10);
  const md = tomorrow.slice(5);
  let label = "", closed = 0, reduced = 0;
  Object.keys(country.config).forEach((k) => {
    (country.config[k].holidays || []).forEach((h) => {
      if (h && (h.date === md || h.date === tomorrow)) { label = label || h.label || ""; if (h.hours) reduced++; else closed++; }
    });
  });
  if (closed + reduced < 2) return null;
  return { label: String(label).replace(/\s*\(.*\)\s*$/, ""), closed: closed >= reduced };
}
async function sendPushTo(sub, payload) {
  if (!webpushLib || !PUSH_KEYS) return "disabled";
  try {
    await webpushLib.sendNotification(
      { endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } },
      JSON.stringify(payload),
      { vapidDetails: { subject: VAPID_SUBJECT, publicKey: PUSH_KEYS.publicKey, privateKey: PUSH_KEYS.privateKey }, TTL: 12 * 60 * 60 }
    );
    return "sent";
  } catch (err) {
    if (err && (err.statusCode === 404 || err.statusCode === 410)) {
      await dbPool.query(`DELETE FROM push_subscriptions WHERE endpoint = $1`, [sub.endpoint]).catch(() => {});
      return "expired";
    }
    console.error("push send:", err && (err.statusCode || err.message));
    return "error";
  }
}
app.get("/api/cron/push-zilnic", async (req, res) => {
  const secret = process.env.CRON_SECRET || "";
  const auth = String(req.headers.authorization || "");
  const ok = secret ? auth === `Bearer ${secret}` : /vercel-cron/i.test(String(req.headers["user-agent"] || ""));
  if (!ok) { res.status(401).json({ error: "unauthorized" }); return; }
  if (!dbPool) { res.status(503).json({ error: "not_configured" }); return; }
  await initPushKeys();
  if (!pushReady() || !webpushLib) { res.status(200).json({ ok: true, skipped: "push_not_ready" }); return; }
  const today = roNowParts().date;
  const stats = { sent: 0, expired: 0, errors: 0, countries: [] };
  try {
    const { rows } = await dbPool.query(
      `SELECT endpoint, p256dh, auth, country, lang FROM push_subscriptions WHERE country IS NOT NULL AND (last_holiday_push IS NULL OR last_holiday_push < $1::date)`,
      [today]
    );
    const byCountry = {};
    rows.forEach((r) => { (byCountry[r.country] = byCountry[r.country] || []).push(r); });
    for (const cc of Object.keys(byCountry)) {
      const h = tomorrowHolidayFor(cc);
      if (!h) continue;
      stats.countries.push(cc);
      for (const sub of byCountry[cc]) {
        const lang = HOLIDAY_PUSH_TEXTS[sub.lang] ? sub.lang : (sub.lang === "en" ? "uk" : (cc === "ro" ? "ro" : "uk"));
        const T = HOLIDAY_PUSH_TEXTS[lang];
        const countryName = (lang === "ro" ? COUNTRY_NAMES_RO[cc] : COUNTRY_NAMES_EN[cc]) || cc.toUpperCase();
        const result = await sendPushTo(sub, { title: T.title(h.label || countryName), body: (h.closed ? T.closed : T.reduced)(countryName), url: `/${cc}` });
        if (result === "sent") {
          stats.sent++;
          await dbPool.query(`UPDATE push_subscriptions SET last_holiday_push = $1::date WHERE endpoint = $2`, [today, sub.endpoint]).catch(() => {});
        } else if (result === "expired") stats.expired++;
        else stats.errors++;
      }
    }
    res.status(200).json({ ok: true, ...stats });
  } catch (err) {
    console.error("cron push-zilnic:", err.message);
    res.status(500).json({ error: "server_error" });
  }
});

app.post("/api/push-subscribe", async (req, res) => {
  if (!pushReady()) {
    res.status(503).json({ error: "push_not_configured" });
    return;
  }

  const rateOk = await checkRateLimit(hashIp(getClientIp(req)), "push-subscribe", 10, 60);
  if (!rateOk) {
    res.status(429).json({ error: "too_many_requests" });
    return;
  }

  const sub = req.body;
  if (!sub || !sub.endpoint || !sub.keys || !sub.keys.p256dh || !sub.keys.auth) {
    res.status(400).json({ error: "invalid_subscription" });
    return;
  }
  try {
    if (typeof sub.endpoint !== "string" || !/^https:\/\//.test(sub.endpoint) || sub.endpoint.length > 1000) {
      res.status(400).json({ error: "invalid_subscription" });
      return;
    }
    const country = typeof sub.country === "string" && COUNTRIES[sub.country] ? sub.country : null;
    const lang = typeof sub.lang === "string" && /^[a-z]{2}$/.test(sub.lang) ? sub.lang : null;
    try {
      await dbPool.query(
        `INSERT INTO push_subscriptions (endpoint, p256dh, auth, country, lang)
         VALUES ($1, $2, $3, $4, $5)
         ON CONFLICT (endpoint) DO UPDATE SET country = COALESCE(EXCLUDED.country, push_subscriptions.country), lang = COALESCE(EXCLUDED.lang, push_subscriptions.lang)`,
        [sub.endpoint, sub.keys.p256dh, sub.keys.auth, country, lang]
      );
    } catch (e) {
      // coloanele country/lang nu există încă (push-schema.sql nerulat) — salvăm ca înainte
      await dbPool.query(
        `INSERT INTO push_subscriptions (endpoint, p256dh, auth) VALUES ($1, $2, $3) ON CONFLICT (endpoint) DO NOTHING`,
        [sub.endpoint, sub.keys.p256dh, sub.keys.auth]
      );
    }
    res.status(201).json({ ok: true });
  } catch (err) {
    console.error("push-subscribe a eșuat:", err.message);
    res.status(500).json({ error: "server_error" });
  }
});

