app.post("/api/admin/restaurante/:id/:action", async (req, res) => {
  if (!requireAdminApi(req, res)) return;
  if (!dbPool) { res.status(503).json({ error: "not_configured" }); return; }
  const { id, action } = req.params;
  if (!["aproba", "respinge", "repending", "sterge"].includes(action) || !/^\d+$/.test(id)) { res.status(400).json({ error: "invalid_input" }); return; }
  if (action === "sterge") {
    try {
      const delRow = await fetchListingRow("restaurant_listings", id, null);
      await dbPool.query(`DELETE FROM restaurant_listings WHERE id = $1::integer`, [id]);
      if (delRow) deleteBlobUrls([...collectBlobUrls(delRow)]).catch(() => {});
      res.status(200).json({ ok: true });
    } catch (err) {
      console.error("Ștergere restaurant a eșuat:", err.message);
      res.status(500).json({ error: err.message });
    }
    return;
  }
  const newStatus = action === "aproba" ? "approved" : action === "respinge" ? "rejected" : "pending";
  try {
    const { rows } = await dbPool.query(
      `UPDATE restaurant_listings SET status = $1, actualizat_la = now() WHERE id = $2 RETURNING slug, name, owner_id`,
      [newStatus, id]
    );
    if (action === "aproba" && rows.length) {
      await mergeProposalIntoListing("restaurant", Number(id));
      const ownerRes = await dbPool.query(`SELECT email FROM accommodation_owners WHERE id = $1`, [rows[0].owner_id]);
      if (ownerRes.rows.length) {
        const listingUrl = `${baseUrlFor(req)}/restaurant/${rows[0].slug}`;
        const loginUrl = `${baseUrlFor(req)}/restaurant/login`;
        sendRestaurantApprovalEmail(ownerRes.rows[0].email, rows[0].name, listingUrl, loginUrl).catch((err) => {
          console.error("email de aprobare restaurant a eșuat:", err.message);
        });
      }
    }
    res.status(200).json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: "server_error" });
  }
});

