// escapeHtml normal + apostrof (JSON-LD e text în <script>, dar tot trece prin
// escapeHtml ca să nu se poată închide accidental tag-ul din date introduse liber)
// ------------------------------------------------------------------
// Formatare simplă a descrierii (Bold / Italic / Underline / Centrat),
// scrisă din bara de instrumente a formularului. NU e HTML liber — întâi
// trecem TOT textul prin escapeHtml (nimic din ce scrie proprietarul nu
// poate deveni tag real), abia apoi înlocuim DOAR markerii noștri stricți
// (**...**, *...*, __...__, [center]...[/center]) cu etichetele
// corespunzătoare, pe care le scriem noi, nu userul. Complet sigur
// împotriva injectării de cod, indiferent ce introduce cineva.
// ------------------------------------------------------------------
// Dacă proprietarul selectează mai multe rânduri și apasă „B”, markerii **...** traversează rândurile noi.
// Procesăm pe paragrafe, deci „spargem” formatarea: fiecare rând primește propriii markeri.
function splitFormatAcrossLines(text) {
  const wrap = (inner, m) => inner.split(/(\n+)/).map((part, i) => (i % 2 ? part : (part.trim() ? part.replace(/^(\s*)([\s\S]*?)(\s*)$/, "$1" + m + "$2" + m + "$3") : part))).join("");
  let t = String(text);
  t = t.replace(/\*\*([\s\S]+?)\*\*/g, (all, inner) => (inner.includes("\n") ? wrap(inner, "**") : all));
  t = t.replace(/__([\s\S]+?)__/g, (all, inner) => (inner.includes("\n") ? wrap(inner, "__") : all));
  t = t.replace(/(?<!\*)\*(?!\*)([\s\S]+?)(?<!\*)\*(?!\*)/g, (all, inner) => (inner.includes("\n") ? wrap(inner, "*") : all));
  return t;
}
function renderFormattedDescriptionHtml(text) {
  if (!text) return "";
  const paragraphs = splitFormatAcrossLines(text).split(/\n+/).map((p) => p.trim()).filter(Boolean);
  return paragraphs.map((para) => {
    const centerMatch = para.match(/^\[center\]([\s\S]*)\[\/center\]$/);
    const centered = !!centerMatch;
    const raw = centered ? centerMatch[1] : para;
    let html = escapeHtml(raw);
    html = html.replace(/\*\*([\s\S]+?)\*\*/g, "<strong>$1</strong>");
    html = html.replace(/__([\s\S]+?)__/g, "<u>$1</u>");
    html = html.replace(/\*([\s\S]+?)\*/g, "<em>$1</em>");
    return centered ? `<p style="text-align:center">${html}</p>` : `<p>${html}</p>`;
  }).join("");
}
function truncateAiDescription(text, maxChars) {
  let t = String(text || "").trim();
  if (t.length <= maxChars) return t;
  t = t.slice(0, maxChars);
  const lastBreak = Math.max(t.lastIndexOf(". "), t.lastIndexOf("!\n"), t.lastIndexOf("?\n"), t.lastIndexOf(".\n"));
  if (lastBreak > maxChars * 0.6) t = t.slice(0, lastBreak + 1);
  return t.trim();
}
app.post("/api/cont/genereaza-descriere", accommodationGate, requireAccommodationOwnerApi, async (req, res) => {
  const OPENAI_API_KEY = process.env.OPENAI_API_KEY || "";
  if (!OPENAI_API_KEY) { res.status(503).json({ error: "not_configured", message: "Generarea cu AI nu e disponibilă momentan." }); return; }
  if (!dbPool) { res.status(503).json({ error: "not_configured" }); return; }
  const b = req.body || {};
  const kind = b.kind === "obiectiv" ? "obiectiv" : "cazare";
  const name = typeof b.name === "string" ? b.name.trim().slice(0, 150) : "";
  if (!name) { res.status(400).json({ error: "missing_name" }); return; }
  const lang = b.lang === "en" ? "en" : "ro";
  const remaining = Number.isFinite(b.remaining) ? Math.floor(b.remaining) : 1800;
  const facts = {
    name,
    typeLabel: typeof b.typeLabel === "string" ? b.typeLabel.slice(0, 60) : "",
    city: typeof b.city === "string" ? b.city.slice(0, 100) : "",
    county: typeof b.county === "string" ? b.county.slice(0, 60) : "",
    address: typeof b.address === "string" ? b.address.slice(0, 200) : "",
    capacity: Number.isFinite(b.capacity) ? Math.floor(b.capacity) : null,
    rooms: Number.isFinite(b.rooms) ? Math.floor(b.rooms) : null,
    managedBy: typeof b.managedBy === "string" ? b.managedBy.slice(0, 150) : "",
    accessInfo: typeof b.accessInfo === "string" ? b.accessInfo.slice(0, 100) : "",
    roomTypes: typeof b.roomTypes === "string" ? b.roomTypes.slice(0, 400) : "",
    amenities: Array.isArray(b.amenities) ? b.amenities.filter((x) => typeof x === "string").slice(0, 30).map((x) => x.slice(0, 60)) : [],
  };
  try {
    // Limita fixă: o singură generare gratuită per cont de proprietar —
    // verificăm ÎNAINTE de a chema OpenAI, ca să nu cheltuim degeaba.
    const ownerRow = await dbPool.query(`SELECT ai_description_used FROM accommodation_owners WHERE id = $1::integer`, [req.accommodationOwner.ownerId]);
    if (ownerRow.rows[0] && ownerRow.rows[0].ai_description_used) {
      res.status(403).json({
        error: "limit_reached",
        message: lang === "en"
          ? `You've used your one free AI generation for this account. You can still edit the text below by hand. Enjoying the site and want a new generation? You can support us with a coffee: <a href="https://ko-fi.com/openinghourstoday" target="_blank" rel="noopener">Buy us a coffee</a>.`
          : `Ai folosit generarea gratuită cu AI pentru acest cont. Poți edita în continuare, manual, textul de mai jos. Dacă îți place site-ul și dorești o generare nouă, ne poți susține cu o cafea: <a href="https://ko-fi.com/openinghourstoday" target="_blank" rel="noopener">Cumpără-ne o cafea</a>.`,
      });
      return;
    }
    const rateOk = await checkRateLimit(hashIp(getClientIp(req)), "genereaza-descriere", 5, 60);
    if (!rateOk) { res.status(429).json({ error: "too_many_requests", message: lang === "en" ? "Too many attempts, please wait a bit." : "Prea multe încercări, mai așteaptă puțin." }); return; }

    const prompt = buildDescriptionAiPrompt(kind, facts, lang, remaining);
    const openaiRes = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${OPENAI_API_KEY}` },
      body: JSON.stringify({ model: "gpt-4o-mini", messages: [{ role: "user", content: prompt }], temperature: 0.6, max_tokens: 900 }),
      signal: AbortSignal.timeout(25000),
    });
    if (!openaiRes.ok) {
      const errText = await openaiRes.text().catch(() => "");
      console.error("OpenAI (descriere) a răspuns cu eroare:", openaiRes.status, errText.slice(0, 300));
      res.status(502).json({ error: "openai_error", message: lang === "en" ? "Generation failed. Please try again." : "Generarea a eșuat. Încearcă din nou." });
      return;
    }
    const data = await openaiRes.json();
    const raw = data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
    if (!raw) { res.status(502).json({ error: "openai_empty_response" }); return; }
    const finalText = truncateAiDescription(raw, Math.max(300, Math.min(remaining, 5000)));

    await dbPool.query(`UPDATE accommodation_owners SET ai_description_used = true WHERE id = $1::integer`, [req.accommodationOwner.ownerId]);
    res.status(200).json({ ok: true, text: finalText });
  } catch (err) {
    console.error("genereaza-descriere:", err.message);
    res.status(500).json({ error: "server_error", message: lang === "en" ? "Something went wrong. Please try again." : "Ceva n-a mers. Încearcă din nou." });
  }
});
