function typeDetailsBlockHtml(nonce, lang, typeValue, existing, legacyRoomTypes) {
  const client = TYPE_DETAILS_CLIENT_JS;
  let ex = existing;
  if (typeof ex === "string") { try { ex = JSON.parse(ex); } catch (e) { ex = null; } }
  let legacy = null;
  if (legacyRoomTypes !== undefined && legacyRoomTypes !== null) {
    let lr = legacyRoomTypes;
    if (typeof lr === "string") { try { lr = JSON.parse(lr); } catch (e) { lr = []; } }
    legacy = { roomTypes: Array.isArray(lr) ? lr : [] };
  }
  const hoursIn = ["12:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00", "19:00", "20:00", "22:00"].concat([lang === "en" ? "Flexible" : "Flexibil"]);
  const hoursOut = ["07:00", "08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00"].concat([lang === "en" ? "Flexible" : "Flexibil"]);
  return `<datalist id="dHoursIn">${hoursIn.map((h) => `<option value="${h}">`).join("")}</datalist><datalist id="dHoursOut">${hoursOut.map((h) => `<option value="${h}">`).join("")}</datalist>
<div id="typeDetailsRoot"></div>
<script nonce="${nonce}">
(function(DEF, LANG, INITIAL_TYPE, EXISTING, LEGACY){
${client}
})(${safeJson(typeDetailsClientDef(lang))}, ${safeJson(lang)}, ${safeJson(typeValue)}, ${safeJson(ex && typeof ex === "object" ? ex : null)}, ${safeJson(legacy)});
</script>
`;
}


// Model v3 (pensiune / cabană / A-Frame): o singură unitate = dormitoare (paturi, dotări, baie) + living
function sanitizePensionV3(raw) {
  if (!raw || typeof raw !== "object" || raw.v !== 3) return null;
  const filt = (map, arr, max) => {
    const out = [];
    (Array.isArray(arr) ? arr : []).forEach((k) => { if (typeof k === "string" && (Array.isArray(map) ? map.includes(k) : map[k]) && !out.includes(k) && out.length < (max || 30)) out.push(k); });
    return out;
  };
  const bedrooms = (Array.isArray(raw.bedrooms) ? raw.bedrooms : []).slice(0, 12).map((br) => {
    const b = br && typeof br === "object" ? br : {};
    const bath = b.bath && typeof b.bath === "object" ? b.bath : {};
    return {
      beds: filt(PENSION_BED_KEYS, b.beds, 4),
      amenities: filt(BEDROOM_AMENITIES, b.amenities, 10),
      bath: { type: PENSION_BATH_TYPES[bath.type] ? bath.type : "private", amenities: filt(BATH_AMENITIES, bath.amenities, 10) },
    };
  });
  const lv = raw.living && typeof raw.living === "object" ? raw.living : {};
  let items = lv.has === true ? filt(LIVING_ITEM_KEYS, lv.items, 20) : [];
  if (items.includes("sofa_colt") && items.includes("sofa_ext")) items = items.filter((k) => k !== "sofa_ext"); // se alege una singură
  const seats = parseInt(lv.diningSeats, 10);
  const living = {
    has: lv.has === true, items,
    diningSeats: items.includes("masa") && Number.isInteger(seats) && seats >= 1 && seats <= 20 ? seats : null,
    fireplace: items.includes("semineu") ? filt(FIREPLACE_TYPES, lv.fireplace, 2) : [],
  };
  return { v: 3, rentalMode: RENTAL_MODES[raw.rentalMode] ? raw.rentalMode : "integral", bedrooms, living };
}
// valori derivate din structuri: capacitate, număr de camere, prețuri și facilități pentru căutare
function derivePensionNumbers(d) {
  const parseN = (v) => parseInt(String(v), 10) || 0;
  let rooms = 0, cap = 0;
  const weekdays = [], weekends = [], amen = new Set();
  d.structures.forEach((st) => {
    rooms += st.bedrooms.length || 1;
    cap += parseN(st.adults) + parseN(st.children);
    if (d.rentalMode !== "integral") {
      if (st.priceWeekday > 0) weekdays.push(st.priceWeekday);
      if (st.priceWeekend > 0) weekends.push(st.priceWeekend);
    }
    st.facilities.forEach((k) => amen.add(k));
    st.bedrooms.forEach((br) => br.amenities.forEach((k) => { if (k === "smart_tv" || k === "aer_conditionat") amen.add(k); }));
    st.living.amenities.forEach((k) => { if (k === "smart_tv" || k === "aer_conditionat") amen.add(k); });
    if (st.kitchen.type === "completa") amen.add("bucatarie_utilata");
    if (st.kitchen.appliances.includes("masina_vase")) amen.add("masina_spalat_vase");
    if (st.kitchen.appliances.includes("espressor")) amen.add("espressor");
  });
  const prices = weekdays.slice();
  if (d.rentalMode !== "camere" && d.priceWeekday > 0) prices.push(d.priceWeekday);
  return {
    rooms: Math.max(1, rooms), capacity: Math.max(1, cap),
    price: prices.length ? Math.min(...prices) : null,
    roomWeekday: weekdays.length ? Math.min(...weekdays) : null,
    roomWeekend: weekends.length ? Math.min(...weekends) : null,
    amenities: [...amen],
  };
}
// valori derivate (capacitate, număr de locuri/unități, preț „de la”) pentru camping
function deriveCampingNumbers(d) {
  const tn = d.tents.on ? (d.tents.count || 0) : 0, cn = d.caravans.on ? (d.caravans.count || 0) : 0;
  let rooms = tn + cn;
  let cap = tn * 3 + cn * 4;
  const prices = [d.tents.on ? d.tents.price : null, d.caravans.on ? d.caravans.price : null];
  Object.keys(d.units).forEach((k) => { rooms += d.units[k].count; cap += d.units[k].count * d.units[k].capacity; prices.push(d.units[k].price); });
  let valid = prices.filter((x) => x !== null && x !== undefined && x > 0);
  // tariful pe adult e „de la” doar dacă nu există preț de loc/unitate
  if (!valid.length && d.fees.adult > 0) valid = [d.fees.adult];
  return { rooms: Math.max(1, rooms), capacity: Math.max(1, cap), price: valid.length ? Math.min(...valid) : null };
}

// Pagina unui loc propus de comunitate și aprobat de admin (restaurant /
// cafenea). Nu are proprietar cu cont, deci arătăm doar ce știm sigur:
// programul și linkul de hartă trimise la propunere.
// =====================================================================
// REVENDICAREA paginii unui loc propus + panoul „Recenzii” al proprietarului
// =====================================================================
// =====================================================================
// REVENDICARE → „Completează pagina”: propunerea devine anunț al proprietarului
// (preumplut din propunere); la aprobarea anunțului, recenziile se mută și
// propunerea nu mai apare ca loc propus.
// =====================================================================
let MERGED_CACHE = { at: 0, ids: new Set() };
async function getMergedProposalIds(force) {
  if (!dbPool) return new Set();
  if (!force && Date.now() - MERGED_CACHE.at < 60000) return MERGED_CACHE.ids;
  try {
    const { rows } = await dbPool.query(`SELECT proposal_id FROM place_merges`);
    MERGED_CACHE = { at: Date.now(), ids: new Set(rows.map((r) => r.proposal_id)) };
  } catch (e) { MERGED_CACHE = { at: Date.now(), ids: new Set() }; }
  return MERGED_CACHE.ids;
}
function proposalScheduleToTimes(raw) {
  let sch = raw;
  if (typeof raw === "string") { try { sch = JSON.parse(raw); } catch (e) { sch = null; } }
  if (!sch || typeof sch !== "object") return {};
  if (sch.is247) return { weekday_open: "00:00", weekday_close: "23:59", saturday_open: "00:00", saturday_close: "23:59", sunday_open: "00:00", sunday_close: "23:59" };
  const d = sch.days || {};
  const get = (i) => { const x = d[String(i)]; return x && !x.closed && x.open && x.close ? x : null; };
  const wk = get(1) || get(2) || get(3) || get(4) || get(5), sa = get(6), su = get(0);
  const out = {};
  if (wk) { out.weekday_open = wk.open; out.weekday_close = wk.close; }
  if (sa) { out.saturday_open = sa.open; out.saturday_close = sa.close; }
  if (su) { out.sunday_open = su.open; out.sunday_close = su.close; }
  return out;
}
// propunerea aprobată și revendicată (aprobat) de acest proprietar, din România, încă nemutată
async function verifyOwnProposal(ownerId, proposalId) {
  if (!dbPool || !Number.isInteger(ownerId) || !Number.isInteger(proposalId)) return null;
  try {
    const { rows } = await dbPool.query(`SELECT id, type, name, city, category, note, schedule, other_type FROM pending_submissions WHERE id = $1::integer AND status = 'approved' AND claimed_by_owner_id = $2::integer AND country_code = 'ro'`, [proposalId, ownerId]);
    if (!rows.length) return null;
    if ((await getMergedProposalIds()).has(rows[0].id)) return null;
    return rows[0];
  } catch (e) { return null; }
}
// datele propunerii, în forma „anunț” folosită de formularele de restaurant / obiectiv
async function buildProposalPrefill(ownerId, proposalId, kind) {
  const p = await verifyOwnProposal(ownerId, proposalId);
  if (!p) return null;
  const isFood = p.type === "restaurant" || p.type === "cafe";
  if ((kind === "restaurant") !== isFood) return null;
  // Mai multe localități cu același nume (ex. 17 × „Costești”)? Nu ghicim județul: proprietarul îl alege.
  const wantCity = normalizeSlug(p.city || "");
  const cands = searchSiruta(p.city, 40);
  const exactHits = cands.filter((h) => normalizeSlug(h.nume) === wantCity);
  let hit = null, ambiguous = 0;
  if (exactHits.length === 1) hit = exactHits[0];
  else if (exactHits.length > 1) ambiguous = exactHits.length;
  else if (cands.length === 1) hit = cands[0];
  else if (cands.length > 1) ambiguous = cands.length;
  const t = { name: p.name, city: hit ? hit.nume : p.city, city_siruta: hit ? String(hit.siruta) : "", county: hit ? hit.judetNume : "", _cityAmbiguous: ambiguous, _fromProposal: p.id, ...proposalScheduleToTimes(p.schedule) };
  if (kind === "restaurant") { t.venue_type = p.type === "cafe" ? "cafenea" : "restaurant"; }
  else { t.venue_type = "altul"; t.venue_type_other = p.type === "beach" ? "Plajă" : (p.other_type || p.category || ""); if (p.note) t.description = p.note; }
  return t;
}
// la aprobarea unui anunț născut dintr-o propunere: mută recenziile și ascunde propunerea
async function mergeProposalIntoListing(kind, listingId) {
  if (!dbPool || !Number.isInteger(listingId)) return;
  const table = kind === "restaurant" ? "restaurant_listings" : "attraction_listings";
  try {
    const { rows } = await dbPool.query(`SELECT source_proposal_id FROM ${table} WHERE id = $1::integer`, [listingId]);
    const pid = rows[0] && rows[0].source_proposal_id;
    if (!pid) return;
    await dbPool.query(`INSERT INTO place_merges (proposal_id, kind, listing_id) VALUES ($1::integer, $2, $3::integer) ON CONFLICT (proposal_id) DO UPDATE SET kind = EXCLUDED.kind, listing_id = EXCLUDED.listing_id, merged_at = now()`, [pid, kind, listingId]);
    await dbPool.query(`UPDATE place_reviews SET place_kind = $1, place_id = $2::integer WHERE place_kind = 'loc' AND place_id = $3::integer`, [kind, listingId, pid]);
    MERGED_CACHE.at = 0; LOCAL_SEARCH_CACHE.at = 0;
  } catch (e) { if (!(e && (e.code === "42703" || e.code === "42P01"))) console.error("mergeProposalIntoListing:", e.message); }
}
