app.get("/revendica/:id", accommodationGate, async (req, res) => {
  const id = /^\d+$/.test(req.params.id) ? Number(req.params.id) : null;
  if (!id || !dbPool) { res.redirect("/"); return; }
  try {
    const q = await dbPool.query(`SELECT id FROM pending_submissions WHERE id = $1::integer AND status = 'approved' AND country_code = 'ro' AND type IN ('restaurant', 'cafe', 'attraction', 'beach', 'other')`, [id]);
    if (!q.rows.length) { res.redirect("/"); return; }
  } catch (e) { res.redirect("/"); return; }
  appendSetCookie(res, `claimPlace=${id}; Path=/; Max-Age=86400; SameSite=Lax; Secure`);
  res.redirect(getAccommodationOwnerSession(req) ? "/cont/revendica" : "/cazare/login");
});
