      <div><div class="title">${L("Atracții", "Attractions")} ${attractionsLink.isNearby ? `${L("lângă", "near")} ${escapeHtml(cityFilter)}` : `${L("în", "in")} ${escapeHtml(attractionsLink.label)}`}</div><div class="sub">${L("Ce să vezi și să vizitezi", "What to see and visit")}</div></div>
